    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $top = $m * $n;

        $parent = array();
        $size = array();
        for ($i = 0; $i <= $top; $i++) {
            $parent[$i] = $i;
            $size[$i] = 1;
        }

        $find = function($x) use (&$parent) {
            $root = $x;
            while ($parent[$root] !== $root) {
                $root = $parent[$root];
            }
            while ($parent[$x] !== $root) {
                $next = $parent[$x];
                $parent[$x] = $root;
                $x = $next;
            }
            return $root;
        };

        $union = function($a, $b) use ($find, &$parent, &$size) {
            $ra = $find($a);
            $rb = $find($b);
            if ($ra === $rb) return;
            if ($size[$ra] < $size[$rb]) {
                $tmp = $ra; $ra = $rb; $rb = $tmp;
