```php
class Solution {

    /** @var int[] */
    private $parent;
    /** @var int[] */
    private $sz;

    private function find($x) {
        $p = $this->parent;
        $root = $x;
        while ($p[$root] !== $root) {
            $root = $p[$root];
        }
        // path compression
        while ($this->parent[$x] !== $root) {
            $next = $this->parent[$x];
            $this->parent[$x] = $root;
            $x = $next;
        }
        return $root;
    }

    private function union($a, $b) {
        $ra = $this->find($a);
        $rb = $this->find($b);
        if ($ra === $rb) {
            return;
        }
        if ($this->sz[$ra] < $this->sz[$rb]) {
            $t = $ra;
            $ra = $rb;
            $rb = $t;
        }
        $this->parent[$rb] = $ra;
        $this->sz[$ra] += $this->sz[$rb];
    }

    /**
     * @param Integer[][] $grid
     * @param Integer[][] $hits
     * @return Integer[]
     */
    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $top = $m * $n;

        $this->parent = array();
        $this->sz = array();
        for ($i = 0; $i <= $top; $i++) {
            $this->parent[$i] = $i;
            $this->sz[$i] = 1;
        }

        // Work on a copy; mark hit bricks with 2 (erased).
        $g = $grid;
        foreach ($hits as $h) {
            $r = $h[0];
            $c = $h[1];
            if ($g[$r][$c] == 1) {
                $g[$r][$c] = 2;
            }
        }

        // Build DSU over remaining bricks (union with top neighbor and left neighbor).
        for ($r = 0; $r < $m; $r++) {
            $row = $g[$r];
            $upRow = ($r > 0) ? $g[$r - 1] : null;
            for ($c = 0; $c < $n; $c++) {
                if ($row[$c] !== 1) continue;
                $id = $r * $n + $c;
                if ($r === 0) {
                    $this->union($id, $top);
                } elseif ($upRow[$c] === 1) {
                    $this->union($id, ($r - 1) * $n + $c);
                }
                if ($c > 0 && $row[$c - 1] === 1) {
                    $this->union($id, $id - 1);
                }
            }
        }

        $k = count($hits);
        $result = array_fill(0, $k, 0);

        for ($i = $k - 1; $i >= 0; $i--) {
            $r = $hits[$i][0];
            $c = $hits[$i][1];
            if ($g[$r][$c] !== 2) {
                continue; // no brick at this position originally
            }
            $g[$r][$c] = 1;
            $id = $r * $n + $c;
            $before = $this->sz[$this->find($top)];
            if ($r === 0) {
                $this->union($id, $top);
            }
            if ($r > 0 && $g[$r - 1][$c] === 1) {
                $this->union($id, ($r - 1) * $n + $c);
            }
            if ($r + 1 < $m && $g[$r + 1][$c] === 1) {
                $this->union($id, ($r + 1) * $n + $c);
            }
            if ($c > 0 && $g[$r][$c - 1] === 1) {
                $this->union($id, $id - 1);
            }
            if ($c + 1 < $n && $g[$r][$c + 1] === 1) {
                $this->union($id, $id + 1);
            }
            $after = $this->sz[$this->find($top)];
            $fallen = $after - $before - 1;
            $result[$i] = $fallen > 0 ? $fallen : 0;
        }

        return $result;
    }
}
