            $x = $p[$x];
        }
        return $x;
    }

    private function union($a, $b) {
        $ra = $this->find($a);
        $rb = $this->find($b);
        if ($ra === $rb) {
            return;
        }
        if ($this->sz[$ra] < $this->sz[$rb]) {
            $t = $ra; $ra = $rb; $rb = $t;
        }
        $this->parent[$rb] = $ra;
        $this->sz[$ra] += $this->sz[$rb];
    }

    /**
     * @param Integer[][] $grid
     * @param Integer[][] $hits
     * @return Integer[]
     */
    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $top = $m * $n;

        $this->parent = [];
        $this->sz = [];
        for ($i = 0; $i <= $top; $i++) {
            $this->parent[$i] = $i;
            $this->sz[$i] = 1;
        }

        $g = $grid;
        foreach ($hits as $h) {
            if ($g[$h[0]][$h[1]] == 1) {
                $g[$h[0]][$h[1]] = 2;
            }
        }

        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                if ($g[$r][$c] == 1) {
                    $id = $r * $n + $c;
                    if ($r == 0) {
                        $this->union($id, $top);
                    } elseif ($g[$r - 1][$c] == 1) {
                        $this->union($id, $id - $n);
                    }
                    if ($c > 0 && $g[$r][$c - 1] == 1) {
                        $this->union($id, $id - 1);
                    }
                }
            }
        }

        $k = count($hits);
        $result = array_fill(0, $k, 0);

        for ($i = $k - 1; $i >= 0; $i--) {
            $r = $hits[$i][0];
            $c = $hits[$i][1];
            if ($g[$r][$c] != 2) {
                continue;
            }
            $g[$r][$c] = 1;
            $id = $r * $n + $c;
            $before = $this->sz[$this->find($top)];
            if ($r == 0) {
                $this->union($id, $top);
