class Solution {

    /** @var int[] */
    private $parent;
    /** @var int[] */
    private $sz;

    private function find($x) {
        while ($this->parent[$x] !== $x) {
            $this->parent[$x] = $this->parent[$this->parent[$x]];
            $x = $this->parent[$x];
        }
        return $x;
    }

    private function union($a, $b) {
        $ra = $this->find($a);
        $rb = $this->find($b);
        if ($ra === $rb) {
            return;
        }
