    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $top = $m * $n;

        $this->parent = array();
        $this->sz = array();
        for ($i = 0; $i <= $top; $i++) {
            $this->parent[$i] = $i;
            $this->sz[$i] = 1;
