                    } elseif ($g[$r - 1][$c] == 1) {
                        $this->union($id, $id - $n);
                    }
                    if ($c > 0 && $g[$r][$c - 1] == 1) {
                        $this->union($id, $id - 1);
                    }
                }
            }
        }

        $k = count($hits);
        $result = array_fill(0, $k, 0);

        // Process hits in reverse, restoring bricks.
        for ($i = $k - 1; $i >= 0; $i--) {
