```php
class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $MOD = 1000000007;
        sort($arr);
        $n = count($arr);
        $index = array_flip($arr); // value => index
        $dp = array_fill(0, $n, 1);
        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $i; $j++) {
                if ($arr[$i] % $arr[$j] === 0) {
                    $ complement = $arr[$i] / $arr[$j];
                    if (isset($index[$complement])) {
                        $dp[$i] = ($dp[$i] + $dp[$j] * $dp[$index[$complement]]) % $MOD;
                    }
                }
            }
        }
        $ans = 0;
        for ($i = 0; $i < $n; $i++) {
            $ans = ($ans + $dp[$i]) % $MOD;
        }
        return $ans;
    }
}
