```php
class MKAverage {
    private $m;
    private $k;
    private $q;
    private $head;
    private $size;
    private $maxV;
    private $cntTree;
    private $sumTree;

    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;
        $this->q = [];
        $this->head = 0;
        $this->size = 0;
        $this->maxV = 100000;
        $this->cntTree = array_fill(0, $this->maxV + 1, 0);
        $this->sumTree = array_fill(0, $this->maxV + 1, 0);
    }

    private function add($num, $d) {
        $v = $this->maxV;
        for ($i = $num; $i <= $v; $i += $i & (-$i)) {
            $this->cntTree[$i] += $d;
            $this->sumTree[$i] += $d * $num;
        }
    }

    private function sumOfSmallest($t) {
        if ($t <= 0) return 0;
        $pos = 0;
        $cnt = 0;
        $sum = 0;
        for ($pw = 65536; $pw > 0; $pw >>= 1) {
            $next = $pos + $pw;
            if ($next <= $this->maxV && $cnt + $this->cntTree[$next] < $t) {
                $pos = $next;
                $cnt += $this->cntTree[$next];
                $sum += $this->sumTree[$next];
            }
        }
        return $sum + ($t - $cnt) * ($pos + 1);
    }

    function addElement($num) {
        $this->q[] = $num;
        $this->size++;
        $this->add($num, 1);
        if ($this->size > $this->m) {
            $old = $this->q[$this->head++];
            $this->add($old, -1);
            $this->size--;
            if ($this->head >= $this->m) {
                $this->q = array_slice($this->q, $this->head);
                $this->head = 0;
            }
        }
    }

    function calculateMKAverage() {
        if ($this->size < $this->m) return -1;
        $midCnt = $this->m - 2 * $this->k;
        $s1 = $this->sumOfSmallest($this->k);
        $s2 = $this->sumOfSmallest($this->m - $this->k);
        return intdiv($s2 - $s1, $midCnt);
    }
}

