class CustomStack {
    private $stack;
    private $add;
    private $maxSize;
    private $n;

    function __construct($maxSize) {
        $this->stack = [];
        $this->add = [];
        $this->maxSize = $maxSize;
        $this->n = 0;
    }

    function push($x) {
        if ($this->n < $this->maxSize) {
            $this->stack[$this->n] = $x;
            $this->add[$this->n] = 0;
            $this->n++;
        }
        return null;
    }

