        if ($this->n === 0) return -1;
        $this->n--;
        $res = $this->stack[$this->n] + $this->add[$this->n];
        if ($this->n > 0) {
            $this->add[$this->n - 1] += $this->add[$this->n];
        }
        $this->add[$this->n] = 0;
        return $res;
    }

    function increment($k, $val) {
        if ($this->n > 0) {
            $idx = min($k, $this->n) - 1;
            $this->add[$idx] += $val;
        }
        return null;
    }
