class CustomStack {
    private $stack;
    private $add;
    private $maxSize;
    private $n;

    /**
     * @param Integer $maxSize
     */
    function __construct($maxSize) {
        $this->stack = [];
        $this->add = [];
        $this->maxSize = $maxSize;
        $this->n = 0;
    }

    /**
     * @param Integer $x
     * @return NULL
     */
    function push($x) {
        if ($this->n < $this->maxSize) {
            $this->stack[$this->n] = $x;
            $this->add[$this->n] = 0;
            $this->n++;
        }
        return null;
    }

    /**
     * @return Integer
     */
    function pop() {
        if ($this->n === 0) {
            return -1;
        }
        $this->n--;
        $res = $this->stack[$this->n] + $this->add[$this->n];
        if ($this->n > 0) {
            $this->add[$this->n - 1] += $this->add[$this->n];
        }
        $this->add[$this->n] = 0;
        return $res;
    }

    /**
     * @param Integer $k
     * @param Integer $val
     * @return NULL
     */
    function increment($k, $val) {
        if ($this->n > 0) {
            $idx = min($k, $this->n) - 1;
            $this->add[$idx] += $val;
        }
        return null;
    }
}
```

This is O(1) per operation. Good.

