class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxEqualFreq($nums) {
        $n = count($nums);
        $cnt = array_fill(0, 100001, 0);
        $freqCount = array_fill(0, 100001, 0);
        $maxF = 0;
        $distinct = 0;
        $ans = 0;

        for ($i = 0; $i < $n; $i++) {
            $x = $nums[$i];

            if ($cnt[$x] === 0) {
                $distinct++;
            } else {
                $freqCount[$cnt[$x]]--;
            }

            $cnt[$x]++;
            $freqCount[$cnt[$x]]++;

            if ($cnt[$x] > $maxF) {
                $maxF = $cnt[$x];
