class Solution {
    function eventualSafeNodes($graph) {
        $n = count($graph);
        $reverse = array_fill(0, $n, []);
        $outDegree = array_fill(0, $n, 0);
        for ($i = 0; $i < $n; $i++) {
            $outDegree[$i] = count($graph[$i]);
            foreach ($graph[$i] as $j) {
                $reverse[$j][] = $i;
            }
        }
        $queue = new SplQueue();
        for ($i = 0; $i < $n; $i++) {
            if ($outDegree[$i] == 0) {
                $queue->enqueue($i);
            }
        }
        $safe = array_fill(0, $n, false);
        while (!$queue->isEmpty()) {
            $node = $queue->dequeue();
            $safe[$node] = true;
            foreach ($reverse[$node] as $prev) {
                $outDegree[$prev]--;
                if ($outDegree[$prev] == 0) {
                    $queue->enqueue($prev);
                }
            }
        }
        $result = [];
        for ($i = 0; $i < $n; $i++) {
            if ($safe[$i]) $result[] = $i;
        }
        return $result;
    }
}
```

