    function maxRunTime($n, $batteries) {
        sort($batteries);
        $total = array_sum($batteries);
        $i = count($batteries) - 1;

        // A battery larger than the current even share (total/n) can single-handedly
        // power one computer for the entire optimal time, so dedicate it to one
        // computer and solve the reduced problem with the remaining batteries.
        while ($n > 1 && $i >= 0 && $batteries[$i] * $n > $total) {
