     * @param Integer[][] $grid
     * @return Integer
     */
    function largestMagicSquare($grid) {
        $m = count($grid);
        $n = count($grid[0]);

        // Prefix sums along rows: rowPre[i][j] = sum of grid[i][0..j-1]
        $rowPre = [];
        for ($i = 0; $i < $m; $i++) {
            $rowPre[$i][0] = 0;
            for ($j = 0; $j < $n; $j++) {
                $rowPre[$i][$j + 1] = $rowPre[$i][$j] + $grid[$i][$j];
            }
        }

        // Prefix sums along columns: colPre[j][i] = sum of grid[0..i-1][j]
        $colPre = [];
        for ($j = 0; $j < $n; $j++) {
            $colPre[$j][0] = 0;
            for ($i = 0; $i < $m; $i++) {
                $colPre[$j][$i + 1] = $colPre[$j][$i] + $grid[$i][$j];
            }
        }

        for ($k = min($m, $n); $k >= 2; $k--) {
            for ($i = 0; $i + $k <= $m; $i++) {
                for ($j = 0; $j + $k <= $n; $j++) {
                    $target = $rowPre[$i][$j + $k] - $rowPre[$i][$j];

                    // Check all row sums
                    $ok = true;
                    for ($r = 1; $r < $k; $r++) {
                        if ($rowPre[$i + $r][$j + $k] - $rowPre[$i + $r][$j] !== $target) {
                            $ok = false;
                            break;
                        }
                    }
                    if (!$ok) continue;

                    // Check all column sums
                    for ($c = 0; $c < $k; $c++) {
                        if ($colPre[$j + $c][$i + $k] - $colPre[$j + $c][$i] !== $target) {
                            $ok = false;
                            break;
                        }
                    }
                    if (!$ok) continue;

                    // Check both diagonals
                    $d1 = 0;
                    $d2 = 0;
                    for ($r = 0; $r < $k; $r++) {
                        $d1 += $grid[$i + $r][$j + $r];
                        $d2 += $grid[$i + $r][$j + $k - 1 - $r];
                    }
                    if ($d1 === $target && $d2 === $target) {
                        return $k;
                    }
                }
            }
        }

        return 1;
    }
}
