class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function lengthOfLIS($nums) {
        $tails = [];
        foreach ($nums as $num) {
            $lo = 0;
            $hi = count($tails);
            while ($lo < $hi) {
                $mid = intdiv($lo + $hi, 2);
                if ($tails[$mid] < $num) {
                    $lo = $mid + 1;
                } else {
                    $hi = $mid;
                }
            }
            if ($lo == count($tails)) {
