```php
class Solution {
    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $adj[$e[0]][] = [$e[1], $e[2]];
            $adj[$e[1]][] = [$e[0], $e[2]];
        }
        // dist[node][time] = min cost
        $dist = array_fill(0, $n, array_fill(0, $maxTime + 1, PHP_INT_MAX));
        $pq = new SplPriorityQueue();
        $pq->setExtractFlags(SplPriorityQueue::EXTR_BOTH);
        $dist[0][0] = $passingFees[0];
        $pq->insert([0, 0, $passingFees[0]], -$passingFees[0]); // [node, time, cost]
        while (!$pq->isEmpty()) {
            $cur = $pq->extract();
            $data = $cur['data'];
            $node = $data[0]; $time = $data[1]; $cost = $data[2];
            if ($cost > $dist[$node][$time]) continue;
            if ($node == $n - 1) return $cost;
            foreach ($adj[$node] as $edge) {
                $nt = $edge[1]; $w = $edge[2];
                $newTime = $time + $w;
                if ($newTime > $maxTime) continue;
                $newCost = $cost + $passingFees[$nt];
                if ($newCost < $dist[$nt][$newTime]) {
                    $dist[$nt][$newTime] = $newCost;
                    $pq->insert([$nt, $newTime, $newCost], -$newCost);
                }
            }
        }
        return -1;
    }
