```php
class Solution {

    /**
     * @param Integer $maxTime
     * @param Integer[][] $edges
     * @param Integer[] $passingFees
     * @return Integer
     */
    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $adj[$e[0]][] = [$e[1], $e[2]];
            $adj[$e[1]][] = [$e[0], $e[2]];
        }

        $INF = PHP_INT_MAX;
        $dist = array_fill(0, $n, array_fill(0, $maxTime + 1, $INF));
        $bestTime = array_fill(0, $n, $INF);

        $pq = new SplPriorityQueue();
        $dist[0][0] = $passingFees[0];
        $pq->insert([0, 0, $passingFees[0]], -$passingFees[0]);

        while (!$pq->isEmpty()) {
            list($node, $t, $cost) = $pq->extract();

            if ($cost > $dist[$node][$t]) continue;
            if ($node === $n - 1) return $cost;
            if ($t >= $bestTime[$node]) continue;
            $bestTime[$node] = $t;

            foreach ($adj[$node] as $e) {
                $nb = $e[0];
                $nt = $t + $e[1];
                if ($nt > $maxTime) continue;
                $nc = $cost + $passingFees[$nb];
                if ($nc < $dist[$nb][$nt]) {
                    $dist[$nb][$nt] = $nc;
                    $pq->insert([$nb, $nt, $nc], -$nc);
                }
            }
        }

        return -1;
    }
}
```

