class Solution {
    /**
     * @param TreeNode $root
     * @return Integer
     */
    function minDepth($root) {
        if ($root === null) return 0;
        $queue = [[$root, 1]];
        while (!empty($queue)) {
            [$node, $depth] = array_shift($queue);
            if ($node->left === null && $node->right === null) {
                return $depth;
            }
            if ($node->left !== null) {
                $queue[] = [$node->left, $depth + 1];
            }
            if ($node->right !== null) {
                $queue[] = [$node->right, $depth + 1];
            }
        }
        return 0;
    }
}
