                }
                $score[$i][$j] = $s;
            }
        }

        $size = 1 << $m;
        $dp = array_fill(0, $size, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $size; $mask++) {
            if ($dp[$mask] < 0) {
                continue;
            }
            $i = 0;
