class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer[]
     */
    function minSubsequence($nums) {
        rsort($nums);
        $total = array_sum($nums);
        $result = [];
        $taken = 0;
        foreach ($nums as $num) {
            $taken += $num;
            $result[] = $num;
            if ($taken * 2 > $total) {
