            if ($v < $hi) {
                $stack[] = [$v + 1, $hi];
            }
        }

        return ($product - 1 + $MOD) % $MOD;
    }

    /**
     * @param Integer $base
     * @param Integer $exp
     * @param Integer $mod
     * @return Integer
