        $fact = array_fill(0, $n + 1, 1);
        for ($i = 1; $i <= $n; $i++) {
            $fact[$i] = ($fact[$i - 1] * $i) % $MOD;
        }
        $invFact = array_fill(0, $n + 1, 1);
        $invFact[$n] = $this->modPow($fact[$n], $MOD - 2, $MOD);
        for ($i = $n; $i >= 1; $i--) {
            $invFact[$i - 1] = ($invFact[$i] * $i) % $MOD;
        }

        $product = 1;
        $stack = [[1, $n]];
        while (!empty($stack)) {
            $range = array_pop($stack);
            $lo = $range[0];
            $hi = $range[1];
            if ($hi - $lo < 1) continue; // size <= 2 contributes factor 1
            // find value in [lo, hi] with minimum position (the subtree root)
