            $b = $v - $lo;
            $c = (($fact[$a] * $invFact[$b]) % $MOD) * $invFact[$a - $b] % $MOD;
            $product = ($product * $c) % $MOD;
            if ($v > $lo) $stack[] = [$lo, $v - 1];
            if ($v < $hi) $stack[] = [$v + 1, $hi];
        }

        return ($product - 1 + $MOD) % $MOD;
    }

