```php
class Solution {

    /**
     * @param Integer[] $bloomDay
     * @param Integer $m
     * @param Integer $k
     * @return Integer
     */
    function minDays($bloomDay, $m, $k) {
        $n = count($bloomDay);
        if ((float)$m * $k > $n) return -1;

        $lo = min($bloomDay);
        $hi = max($bloomDay);

        $canMake = function($days) use ($bloomDay, $m, $k, $n) {
            $bouquets = 0;
            $flowers = 0;
            for ($i = 0; $i < $n; $i++) {
                if ($bloomDay[$i] <= $days) {
                    $flowers++;
                    if ($flowers == $k) {
                        $bouquets++;
                        $flowers = 0;
                        if ($bouquets >= $m) return true;
                    }
                } else {
                    $flowers = 0;
                }
