class Solution {

    /**
     * @param Integer[] $slices
     * @return Integer
     */
    function maxSizeSlices($slices) {
        $m = count($slices);
        $k = intdiv($m, 3);
        $NEG = -1000000000;
        $ans = 0;

        // Circular problem: never pick both first and last slice.
        // Case 0 uses slices[0..m-2], case 1 uses slices[1..m-1].
        for ($case = 0; $case < 2; $case++) {
            $offset = $case;
            $len = $m - 1;

            // dp over linear array: prev1 = dp[i-1][j], prev2 = dp[i-2][j]
            $prev2 = array_fill(0, $k + 1, $NEG);
            $prev2[0] = 0;
            $prev1 = array_fill(0, $k + 1, $NEG);
            $prev1[0] = 0;

            for ($i = 1; $i <= $len; $i++) {
                $cur = array_fill(0, $k + 1, $NEG);
                $cur[0] = 0;
                $v = $slices[$offset + $i - 1];
                for ($j = 1; $j <= $k; $j++) {
                    $skip = $prev1[$j];
                    $take = $prev2[$j - 1] + $v;
                    $cur[$j] = ($take > $skip) ? $take : $skip;
                }
                $prev2 = $prev1;
                $prev1 = $cur;
            }

            if ($prev1[$k] > $ans) {
                $ans = $prev1[$k];
            }
        }

        return $ans;
    }
}
