class Solution {
    /**
     * @param Integer[] $slices
     * @return Integer
     */
    function maxSizeSlices($slices) {
        $m = count($slices);
        $k = intdiv($m, 3);
        $NEG = -1000000000;

        $case1 = $this->pick($slices, 0, $m - 1, $k, $NEG); // slices[0..m-2]
        $case2 = $this->pick($slices, 1, $m - 1, $k, $NEG); // slices[1..m-1]
        return max($case1, $case2);
    }

    private function pick($slices, $start, $end, $k, $NEG) {
        // consider slices[start..end] inclusive, linear
        $len = $end - $start + 1;
        $prev2 = array_fill(0, $k + 1, $NEG);
        $prev2[0] = 0;
        $prev1 = array_fill(0, $k + 1, $NEG);
        $prev1[0] = 0;
        for ($i = 1; $i <= $len; $i++) {
            $cur = array_fill(0, $k + 1, $NEG);
            $cur[0] = 0;
            $a = $slices[$start + $i - 1];
            for ($j = 1; $j <= $k; $j++) {
                $take = $prev2[$j - 1] + $a;
                $skip = $prev1[$j];
                $cur[$j] = max($skip, $take);
            }
            $prev2 = $prev1;
            $prev1 = $cur;
        }
        return $prev1[$k];
    }
}

