class Solution {

    /**
     * @param Integer[] $slices
     * @return Integer
     */
    function maxSizeSlices($slices) {
        $m = count($slices);
        $k = intdiv($m, 3);
        $NEG = -1000000000;
        $ans = 0;

        // Reduce circular problem to two linear problems:
        // never pick both first and last slice (they are adjacent in the circle).
        for ($case = 0; $case < 2; $case++) {
            $offset = $case; // case 0: slices[0..m-2], case 1: slices[1..m-1]
            $len = $m - 1;

            $prev2 = array_fill(0, $k + 1, $NEG); // dp[i-2]
            $prev2[0] = 0;
            $prev1 = array_fill(0, $k + 1, $NEG); // dp[i-1]
            $prev1[0] = 0;

            for ($i = 1; $i <= $len; $i++) {
                $cur = array_fill(0, $k + 1, $NEG);
                $cur[0] = 0;
                $v = $slices[$offset + $i - 1];
                for ($j = 1; $j <= $k; $j++) {
                    $skip = $prev1[$j];
                    $take = $prev2[$j - 1] + $v;
                    $cur[$j] = max($skip, $take);
                }
                $prev2 = $prev1;
                $prev1 = $cur;
            }

            if ($prev1[$k] > $ans) {
                $ans = $prev1[$k];
            }
        }

        return $ans;
    }
}
