```php
class Solution {

    /**
     * @var String[]
     */
    private $res = [];

    private $s = '';
    private $n = 0;

    /**
     * @param String $s
     * @return String[]
     */
    function removeInvalidParentheses($s) {
        $this->s = $s;
        $this->n = strlen($s);
        $this->res = [];

        // Minimum removals needed:
        // $lRem = unmatched '(' count, $rRem = unmatched ')' count.
        $lRem = 0;
        $rRem = 0;
        for ($i = 0; $i < $this->n; $i++) {
            $c = $this->s[$i];
            if ($c === '(') {
                $lRem++;
            } elseif ($c === ')') {
                if ($lRem > 0) {
                    $lRem--;
                } else {
                    $rRem++;
                }
            }
        }

        $this->dfs(0, 0, $lRem, $rRem, '', false);
        return $this->res;
    }

    /**
     * @param int $i current index in $this->s
     * @param int $open current count of unmatched kept '('
     * @param int $lRem removals of '(' still required
     * @param int $rRem removals of ')' still required
     * @param string $path characters kept so far
     * @param bool $prevRemoved whether s[i-1] was removed in this branch
     */
    private function dfs($i, $open, $lRem, $rRem, $path, $prevRemoved) {
        if ($lRem + $rRem > $this->n - $i) {
            return; // not enough characters left to cover required removals
        }
        if ($i === $this->n) {
            if ($open === 0 && $lRem === 0 && $rRem === 0) {
                $this->res[] = $path;
            }
            return;
        }

        $c = $this->s[$i];
        if ($c === '(') {
            // keep
            $this->dfs($i + 1, $open + 1, $lRem, $rRem, $path . '(', false);
            // remove (avoid duplicates: only remove a '(' that starts a run,
            // or continues removing a run from the left)
            if ($lRem > 0 && ($i === 0 || $this->s[$i - 1] !== '(' || $prevRemoved)) {
                $this->dfs($i + 1, $open, $lRem - 1, $rRem, $path, true);
            }
        } elseif ($c === ')') {
            // keep only if it can be matched
            if ($open > 0) {
                $this->dfs($i + 1, $open - 1, $lRem, $rRem, $path . ')', false);
            }
            // remove
            if ($rRem > 0 && ($i === 0 || $this->s[$i - 1] !== ')' || $prevRemoved)) {
                $this->dfs($i + 1, $open, $lRem, $rRem - 1, $path, true);
            }
        } else {
            $this->dfs($i + 1, $open, $lRem, $rRem, $path . $c, false);
        }
    }
}
