class Solution {

    /**
     * @param String $s
     * @return Integer
     */
    function removePalindromeSub($s) {
        if ($s === '') {
            return 0;
        }
        if ($s === strrev($s)) {
            return 1;
        }
        return 2;
    }
}
```

