class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Integer
     */
    function splitArray($nums, $k) {
        $lo = max($nums);
        $hi = array_sum($nums);

        while ($lo < $hi) {
            $mid = intdiv($lo + $hi, 2);
            if ($this->canSplit($nums, $k, $mid)) {
                $hi = $mid;
            } else {
                $lo = $mid + 1;
            }
