class Solution {

    private $memo;
    private $stickers;
    private $targetChars;
    private $bits;
    private $m;
    private $full;

    /**
     * @param String[] $stickers
     * @param String $target
     * @return Integer
     */
    function minStickers($stickers, $target) {
        $m = strlen($target);
        $this->m = $m;
        $this->full = (1 << $m) - 1;

