            if (!isset($letterIdx[$ch])) {
                $letterIdx[$ch] = count($letterIdx);
            }
            $this->targetChars[$i] = $letterIdx[$ch];
        }
        $k = count($letterIdx);

        $this->bits = [];
        for ($i = 0; $i < $m; $i++) {
            $this->bits[$i] = 1 << $i;
        }

        $cands = [];
        foreach ($stickers as $s) {
            $cnt = array_fill(0, $k, 0);
            $len = strlen($s);
            for ($i = 0; $i < $len; $i++) {
                $ch = $s[$i];
                if (isset($letterIdx[$ch])) {
                    $cnt[$letterIdx[$ch]]++;
                }
            }
            $useful = false;
            for ($c = 0; $c < $k; $c++) {
                if ($cnt[$c] > 0) { $useful = true; break; }
            }
            if ($useful) {
                $cands[] = $cnt;
            }
        }

        $n = count($cands);
        $keep = [];
        for ($i = 0; $i < $n; $i++) {
            $dominated = false;
            for ($j = 0; $j < $n; $j++) {
                if ($j === $i) continue;
                $ci = $cands[$i];
                $cj = $cands[$j];
                $ok = true;
