        $cands = [];
        foreach ($stickers as $s) {
            $cnt = array_fill(0, $k, 0);
            $len = strlen($s);
            for ($i = 0; $i < $len; $i++) {
                $ch = $s[$i];
                if (isset($letterIdx[$ch])) {
