                }
            }
            $useful = false;
            for ($c = 0; $c < $k; $c++) {
                if ($cnt[$c] > 0) { $useful = true; break; }
            }
            if ($useful) {
                $cands[] = $cnt;
            }
        }

        // Drop stickers dominated by others (componentwise <=).
        $n = count($cands);
        $keep = [];
        for ($i = 0; $i < $n; $i++) {
