class Solution {

    /**
     * @param Integer[] $releaseTimes
     * @param String $keysPressed
     * @return String
     */
    function slowestKey($releaseTimes, $keysPressed) {
        $n = count($releaseTimes);
        $maxDuration = $releaseTimes[0];
        $bestKey = $keysPressed[0];

        for ($i = 1; $i < $n; $i++) {
            $duration = $releaseTimes[$i] - $releaseTimes[$i - 1];
            if ($duration > $maxDuration || ($duration == $maxDuration && $keysPressed[$i] > $bestKey)) {
                $maxDuration = $duration;
                $bestKey = $keysPressed[$i];
            }
        }

        return $bestKey;
    }
}
