```php
class Solution {

    /**
     * @param String[] $grid
     * @return Integer
     */
    function regionsBySlashes($grid) {
        $n = count($grid);
        $total = $n * $n * 4;
        $parent = array();
        for ($i = 0; $i < $total; $i++) {
            $parent[$i] = $i;
        }

        // find with path compression
        $find = function($x) use (&$parent) {
            $root = $x;
            while ($parent[$root] !== $root) {
                $root = $parent[$root];
            }
            while ($parent[$x] !== $root) {
                $next = $parent[$x];
                $parent[$x] = $root;
                $x = $next;
            }
            return $root;
        };

        $union = function($a, $b) use (&$parent, $find) {
            $ra = $find($a);
            $rb = $find($b);
            if ($ra !== $rb) {
                $parent[$ra] = $rb;
            }
        };

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $base = ($i * $n + $j) * 4;
                $c = $grid[$i][$j];
                if ($c === ' ') {
                    $union($base + 0, $base + 1);
                    $union($base + 1, $base + 2);
                    $union($base + 2, $base + 3);
                } elseif ($c === '/') {
                    $union($base + 0, $base + 3);
                    $union($base + 1, $base + 2);
                } else { // '\'
                    $union($base + 0, $base + 1);
                    $union($base + 2, $base + 3);
                }

                // connect with right neighbor
                if ($j + 1 < $n) {
                    $union($base + 1, $base + 4 + 3);
                }
                // connect with bottom neighbor
                if ($i + 1 < $n) {
                    $union($base + 2, $base + 4 * $n + 0);
                }
            }
        }

        $count = 0;
        for ($i = 0; $i < $total; $i++) {
            if ($find($i) === $i) {
                $count++;
            }
        }
        return $count;
    }
}
```

