```php
class Solution {

    /**
     * @param String[] $grid
     * @return Integer
     */
    function regionsBySlashes($grid) {
        $n = count($grid);
        $total = $n * $n * 4;
        $parent = [];
        for ($i = 0; $i < $total; $i++) {
            $parent[$i] = $i;
        }

        $find = function ($x) use (&$parent) {
            while ($parent[$x] !== $x) {
                $parent[$x] = $parent[$parent[$x]];
                $x = $parent[$x];
            }
            return $x;
        };

        $union = function ($a, $b) use (&$parent, $find) {
            $ra = $find($a);
            $rb = $find($b);
            if ($ra !== $rb) {
                $parent[$ra] = $rb;
            }
        };

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $base = ($i * $n + $j) * 4;
                $c = $grid[$i][$j];
                if ($c === ' ') {
                    $union($base, $base + 1);
                    $union($base + 1, $base + 2);
                    $union($base + 2, $base + 3);
                } elseif ($c === '/') {
                    $union($base, $base + 3);
                    $union($base + 1, $base + 2);
                } else {
                    $union($base, $base + 1);
                    $union($base + 2, $base + 3);
                }
                if ($j + 1 < $n) {
                    $union($base + 1, $base + 7);
                }
                if ($i + 1 < $n) {
                    $union($base + 2, $base + 4 * $n);
                }
            }
        }

        $regions = 0;
        for ($i = 0; $i < $total; $i++) {
            if ($find($i) === $i) {
                $regions++;
            }
        }
        return $regions;
    }
}
```

