```php
class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer[][] $edges
     * @return Integer[]
     */
    function getCoprimes($nums, $edges) {
        $n = count($nums);
        $ans = array_fill(0, $n, -1);

        // Build adjacency list
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $adj[$e[0]][] = $e[1];
            $adj[$e[1]][] = $e[0];
        }

        // Precompute coprime lists for values 1-50
        $coprime = [];
        for ($i = 1; $i <= 50; $i++) {
            $coprime[$i] = [];
            for ($j = 1; $j <= 50; $j++) {
                if ($this->gcd($i, $j) == 1) {
                    $coprime[$i][] = $j;
                }
            }
        }

        // stacks[v] = list of [depth, node] for nodes with value v on current path
        $stacks = [];
        for ($v = 0; $v <= 50; $v++) {
            $stacks[$v] = [];
        }

        // Iterative DFS
        $dfsStack = [[0, -1, 0]]; // [node, parent, next child index]
        $entered = array_fill(0, $n, false);

        while (count($dfsStack) > 0) {
            $idx = count($dfsStack) - 1;
            $node = $dfsStack[$idx][0];
            $parent = $dfsStack[$idx][1];
            $ci = $dfsStack[$idx][2];

            if (!$entered[$node]) {
                $entered[$node] = true;
                $depth = $idx;
                $v = $nums[$node];

                // Find closest coprime ancestor
                $bestDepth = -1;
                $bestNode = -1;
                foreach ($coprime[$v] as $u) {
                    $cnt = count($stacks[$u]);
                    if ($cnt > 0) {
                        $t = $stacks[$u][$cnt - 1];
                        if ($t[0] > $bestDepth) {
                            $bestDepth = $t[0];
                            $bestNode = $t[1];
                        }
                    }
                }
                $ans[$node] = $bestNode;

                $stacks[$v][] = [$depth, $node];
            }

            // Find next unvisited child
            $numAdj = count($adj[$node]);
            $nextChild = -1;
            while ($ci < $numAdj) {
                $child = $adj[$node][$ci];
                $ci++;
                if ($child != $parent) {
                    $nextChild = $child;
                    break;
                }
            }

            if ($nextChild != -1) {
                $dfsStack[$idx][2] = $ci;
                $dfsStack[] = [$nextChild, $node, 0];
            } else {
                // Done with this node
                $v = $nums[$node];
                array_pop($stacks[$v]);
                array_pop($dfsStack);
            }
        }

        return $ans;
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $a % $b;
            $a = $b;
            $b = $t;
        }
        return $a;
    }
}
