class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer[][] $edges
     * @return Integer[]
     */
    function getCoprimes($nums, $edges) {
        $n = count($nums);
        $ans = array_fill(0, $n, -1);

        // Build adjacency list
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $adj[$e[0]][] = $e[1];
            $adj[$e[1]][] = $e[0];
        }

        // Precompute coprime lists for values 1-50
        $coprime = [];
        for ($i = 1; $i <= 50; $i++) {
            $coprime[$i] = [];
            for ($j = 1; $j <= 50; $j++) {
                if ($this->gcd($i, $j) == 1) {
                    $coprime[$i][] = $j;
                }
            }
        }

        // last[v] = encoded(depth, node) of deepest node with value v on current path, or -1
        $last = array_fill(0, 51, -1);

        // Iterative DFS: each entry is [node, parent, next child index, saved last value]
        $dfsStack = [[0, -1, 0, -1]];
        $entered = array_fill(0, $n, false);

        while (!empty($dfsStack)) {
            $idx = count($dfsStack) - 1;
            $node = $dfsStack[$idx][0];
            $parent = $dfsStack[$idx][1];
            $ci = $dfsStack[$idx][2];

            if (!$entered[$node]) {
                $entered[$node] = true;
                $depth = $idx;
                $v = $nums[$node];

                // Find closest coprime ancestor (before updating last[v])
                $best = -1;
                foreach ($coprime[$v] as $u) {
                    if ($last[$u] > $best) {
                        $best = $last[$u];
                    }
                }
                $ans[$node] = ($best >= 0) ? ($best % $n) : -1;

                // Update last[v] and save old value
                $dfsStack[$idx][3] = $last[$v];
                $last[$v] = $depth * $n + $node;
            }

            // Find next child to process
            $numAdj = count($adj[$node]);
            $nextChild = -1;
            while ($ci < $numAdj) {
                $child = $adj[$node][$ci];
                $ci++;
                if ($child != $parent) {
                    $nextChild = $child;
                    break;
                }
            }

            if ($nextChild != -1) {
                $dfsStack[$idx][2] = $ci;
                $dfsStack[] = [$nextChild, $node, 0, -1];
            } else {
                // Done with this node, restore last[v]
                $v = $nums[$node];
                $last[$v] = $dfsStack[$idx][3];
                array_pop($dfsStack);
            }
        }

        return $ans;
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $a % $b;
            $a = $b;
            $b = $t;
        }
        return $a;
    }
}
