class Solution {

    /**
     * @param Integer $rows
     * @param Integer $cols
     * @param Integer $rStart
     * @param Integer $cStart
     * @return Integer[][]
     */
    function spiralMatrixIII($rows, $cols, $rStart, $cStart) {
        $result = [[$rStart, $cStart]];
        $directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
        $d = 0; // facing east
        $r = $rStart;
        $c = $cStart;
        $step = 1;
        $total = $rows * $cols;

        while (count($result) < $total) {
            // move in current direction $step times, then turn
            for ($i = 0; $i < 2; $i++) {
                for ($j = 0; $j < $step; $j++) {
                    $r += $directions[$d][0];
                    $c += $directions[$d][1];
                    if ($r >= 0 && $r < $rows && $c >= 0 && $c < $cols) {
                        $result[] = [$r, $c];
                    }
                }
                $d = ($d + 1) % 4;
            }
            $step++;
        }

        return $result;
    }
}
