def spiralMatrixIII(self, rows, cols, rStart, cStart):
    directions = [[0,1],[1,0],[0,-1],[-1,0]]
    res = [[rStart, cStart]]
    r, c, d, steps = rStart, cStart, 0, 1
    while len(res) < rows * cols:
        for _ in range(2):
            dr, dc = directions[d]
            for _ in range(steps):
                r += dr; c += dc
                if 0 <= r < rows and 0 <= c < cols:
                    res.append([r, c])
            d = (d + 1) % 4
        steps += 1
    return res
```

