class Solution {
    private $assign = [];
    private $used = [];
    private $leading = [];
    private $columns = []; // each column: [wordChars (with multiplicity), resultChar]
    private $maxLen;

    function isSolvable($words, $result) {
        $resultLen = strlen($result);
        $maxWordLen = 0;
        foreach ($words as $w) $maxWordLen = max($maxWordLen, strlen($w));
        if ($maxWordLen > $resultLen) return false;

        $this->maxLen = $resultLen;
        $this->leading = [];
        foreach ($words as $w) $this->leading[$w[0]] = true;
        $this->leading[$result[0]] = true;

        // Build columns
        $this->columns = [];
        for ($c = 0; $c < $resultLen; $c++) {
            $wordChars = [];
            foreach ($words as $w) {
                $wl = strlen($w);
                if ($c < $wl) {
                    $wordChars[] = $w[$wl - 1 - $c];
                }
            }
            $resChar = $result[$resultLen - 1 - $c];
            $this->columns[] = [$wordChars, $resChar];
        }

        $this->assign = [];
        $this->used = array_fill(0, 10, false);

        return $this->solve(0, 0);
    }

    private function solve($col, $carry) {
        if ($col == $this->maxLen) {
            return $carry == 0;
        }
        list($wordChars, $resChar) = $this->columns[$col];

        // Gather unique unassigned chars
        $toAssign = [];
        $seen = [];
        foreach ($wordChars as $ch) {
            if (!isset($this->assign[$ch]) && !isset($seen[$ch])) {
                $seen[$ch] = true;
                $toAssign[] = $ch;
            }
        }
        if (!isset($this->assign[$resChar]) && !isset($seen[$resChar])) {
            $toAssign[] = $resChar;
        }

        return $this->tryAssign($col, $carry, $toAssign, 0);
    }

    private function tryAssign($col, $carry, $toAssign, $idx) {
        if ($idx == count($toAssign)) {
            // evaluate column
            list($wordChars, $resChar) = $this->columns[$col];
            $sum = $carry;
            foreach ($wordChars as $ch) $sum += $this->assign[$ch];
            $rd = $this->assign[$resChar];
            if ($sum % 10 != $rd) return false;
            $newCarry = intdiv($sum, 10);
            if ($col == $this->maxLen - 1) {
                return $newCarry == 0;
            }
            return $this->solve($col + 1, $newCarry);
        }
        $ch = $toAssign[$idx];
        for ($d = 0; $d <= 9; $d++) {
            if ($this->used[$d]) continue;
            if ($d == 0 && isset($this->leading[$ch])) continue;
            $this->used[$d] = true;
            $this->assign[$ch] = $d;
            if ($this->tryAssign($col, $carry, $toAssign, $idx + 1)) return true;
            unset($this->assign[$ch]);
            $this->used[$d] = false;
        }
        return false;
    }
}
