    function isSolvable($words, $result) {
        $resultLen = strlen($result);
        $maxWordLen = 0;
        foreach ($words as $w) {
            $l = strlen($w);
            if ($l > $maxWordLen) $maxWordLen = $l;
        }
        if ($maxWordLen > $resultLen) return false;

        // assign ids to chars
        $charId = [];
        $id = 0;
        for ($i = 0; $i < $resultLen; $i++) {
            $c = $result[$i];
            if (!isset($charId[$c])) { $charId[$c] = $id++; }
        }
        foreach ($words as $w) {
            $l = strlen($w);
            for ($i = 0; $i < $l; $i++) {
                $c = $w[$i];
                if (!isset($charId[$c])) { $charId[$c] = $id++; }
            }
        }

        $leading = array_fill(0, $id, false);
        foreach ($words as $w) {
            $leading[$charId[$w[0]]] = true;
        }
        $leading[$charId[$result[0]]] = true;
        $this->leading = $leading;

        // build columns
        $colEntries = [];
        $colRes = [];
        for ($c = 0; $c < $resultLen; $c++) {
            $cnt = [];
            foreach ($words as $w) {
                $l = strlen($w);
                if ($c < $l) {
                    $cid = $charId[$w[$l - 1 - $c]];
                    $cnt[$cid] = ($cnt[$cid] ?? 0) + 1;
                }
            }
            $entries = [];
            foreach ($cnt as $cid => $m) $entries[] = [$cid, $m];
            $colEntries[] = $entries;
            $colRes[] = $charId[$result[$resultLen - 1 - $c]];
        }
        $this->colEntries = $colEntries;
        $this->colRes = $colRes;
        $this->nCols = $resultLen;

        $this->assign = array_fill(0, $id, -1);
        $this->usedMask = 0;

        return $this->solveCol(0, 0);
    }

    private function solveCol($col, $carry) {
        if ($col >= $this->nCols) return $carry == 0;

        $base = $carry;
        $toAssign = [];
        $seenMask = 0;
        foreach ($this->colEntries[$col] as $e) {
            $cid = $e[0];
            $a = $this->assign[$cid];
            if ($a >= 0) {
                $base += $e[1] * $a;
            } elseif (($seenMask & (1 << $cid)) == 0) {
                $seenMask |= (1 << $cid);
                $toAssign[] = $e;
            }
