```php
class Solution {
    private $assign;
    private $usedMask;
    private $leading;
    private $colEntries;
    private $colRes;
    private $nCols;

    /**
     * @param String[] $words
     * @param String $result
     * @return Boolean
     */
    function isSolvable($words, $result) {
        $resultLen = strlen($result);
        $maxWordLen = 0;
        foreach ($words as $w) {
            $l = strlen($w);
            if ($l > $maxWordLen) {
                $maxWordLen = $l;
            }
        }
        if ($maxWordLen > $resultLen) {
            return false;
        }

        $charId = [];
        $id = 0;
        for ($i = 0; $i < $resultLen; $i++) {
            $c = $result[$i];
            if (!isset($charId[$c])) {
                $charId[$c] = $id++;
            }
        }
        foreach ($words as $w) {
            $l = strlen($w);
            for ($i = 0; $i < $l; $i++) {
                $c = $w[$i];
                if (!isset($charId[$c])) {
                    $charId[$c] = $id++;
                }
            }
        }
        if ($id > 10) {
            return false;
        }

        $leading = array_fill(0, $id, false);
        foreach ($words as $w) {
            $leading[$charId[$w[0]]] = true;
        }
        $leading[$charId[$result[0]]] = true;
        $this->leading = $leading;

        $colEntries = [];
        $colRes = [];
        for ($c = 0; $c < $resultLen; $c++) {
            $cnt = [];
            foreach ($words as $w) {
                $l = strlen($w);
                if ($c < $l) {
                    $cid = $charId[$w[$l - 1 - $c]];
                    if (isset($cnt[$cid])) {
                        $cnt[$cid]++;
                    } else {
                        $cnt[$cid] = 1;
                    }
                }
            }
            $entries = [];
            foreach ($cnt as $cid => $m) {
                $entries[] = [$cid, $m];
            }
            $colEntries[] = $entries;
            $colRes[] = $charId[$result[$resultLen - 1 - $c]];
        }
        $this->colEntries = $colEntries;
        $this->colRes = $colRes;
        $this->nCols = $resultLen;

        $this->assign = array_fill(0, $id, -1);
        $this->usedMask = 0;

        return $this->solveCol(0, 0);
    }

    private function solveCol($col, $carry) {
        if ($col >= $this->nCols) {
            return $carry == 0;
        }
        $sum = $carry;
        $toAssign = [];
        foreach ($this->colEntries[$col] as $e) {
            $cid = $e[0];
            $a = $this->assign[$cid];
            if ($a >= 0) {
                $sum += $e[1] * $a;
            } else {
                $toAssign[] = $e;
            }
        }
        return $this->assignChars($col, $toAssign, 0, $sum);
    }

    private function assignChars($col, $toAssign, $idx, $sum) {
        $cnt = count($toAssign);
        if ($idx === $cnt) {
            $needed = $sum % 10;
            $newCarry = intdiv($sum, 10);
            if ($col === $this->nCols - 1 && $newCarry !== 0) {
                return false;
            }
            $resCid = $this->colRes[$col];
            $a = $this->assign[$resCid];
            if ($a >= 0) {
                if ($a !== $needed) {
                    return false;
                }
                return $this->solveCol($col + 1, $newCarry);
            }
            if (($this->usedMask & (1 << $needed)) !== 0) {
                return false;
            }
            if ($needed === 0 && $this->leading[$resCid]) {
                return false;
            }
            $this->usedMask |= (1 << $needed);
            $this->assign[$resCid] = $needed;
            if ($this->solveCol($col + 1, $newCarry)) {
                return true;
            }
            $this->usedMask &= ~(1 << $needed);
            $this->assign[$resCid] = -1;
            return false;
        }
        $e = $toAssign[$idx];
        $cid = $e[0];
        $mult = $e[1];
        $start = $this->leading[$cid] ? 1 : 0;
        for ($d = $start; $d <= 9; $d++) {
            if (($this->usedMask & (1 << $d)) !== 0) {
                continue;
            }
            $this->usedMask |= (1 << $d);
            $this->assign[$cid] = $d;
            if ($this->assignChars($col, $toAssign, $idx + 1, $sum + $mult * $d)) {
                return true;
            }
            $this->usedMask &= ~(1 << $d);
        }
        $this->assign[$cid] = -1;
        return false;
    }
}
