```php
class Solution {

    /**
     * @param Integer $a
     * @param Integer $b
     * @return String
     */
    function strWithout3a3b($a, $b) {
        $res = '';
        while ($a > 0 || $b > 0) {
            if ($a > $b) {
                $take = min(2, $a);
                $res .= str_repeat('a', $take);
                $a -= $take;
                if ($b > 0) {
                    $res .= 'b';
                    $b--;
                }
            } elseif ($b > $a) {
                $take = min(2, $b);
                $res .= str_repeat('b', $take);
                $b -= $take;
                if ($a > 0) {
                    $res .= 'a';
                    $a--;
                }
            } else {
                $res .= 'ab';
                $a--;
                $b--;
            }
        }
        return $res;
    }
}
```

