```php
class Solution {

    /**
     * @param String $beginWord
     * @param String $endWord
     * @param String[] $wordList
     * @return Integer
     */
    function ladderLength($beginWord, $endWord, $wordList) {
        $wordSet = array_flip($wordList);
        if (!isset($wordSet[$endWord])) {
            return 0;
        }
        unset($wordSet[$beginWord]);

        $queue = [$beginWord];
        $level = 1;
        $wordLen = strlen($beginWord);
        $letters = range('a', 'z');

        while (count($queue) > 0) {
            $nextQueue = [];
            $level++;
            foreach ($queue as $word) {
                for ($i = 0; $i < $wordLen; $i++) {
                    $original = $word[$i];
                    foreach ($letters as $ch) {
                        if ($ch === $original) {
                            continue;
                        }
                        $word[$i] = $ch;
                        if (isset($wordSet[$word])) {
                            if ($word === $endWord) {
                                return $level;
                            }
                            $nextQueue[] = $word;
                            unset($wordSet[$word]);
                        }
                    }
                    $word[$i] = $original;
                }
            }
            $queue = $nextQueue;
        }

        return 0;
    }
}
